// ========== 淘小说 11.2.8 运维面板 ==========
// 全部函数挂在 loginUrl；SourceLoginDialog 用 "$loginJS\n$action" 一起 eval。
// 绑定差异（源码级实锤）：loginUi<js> 无 source/java；按钮 action 有 java(SourceLoginJsExtensions)
// 且 source 仍绑定；viewName 表达式用 source 可用但不保证 java ⇒ 视图函数只读 source。
// 兼容 LT(gedoor/LegadoTeam) 与 E(Luoyacheng/legado-E)：V1 静态 loginUi 是 E 版唯一可用形态。

var TX_MAX = 6;
var TX_PUB_DEFAULT = 'https://m.taoyuewenhua.com';
var TX_API_DEFAULT = 'https://tybook.taoyuewenhua.net';
var TX_CDN_DEFAULT = 'https://scdn.taoyuewenhua.net';
var TX_UA = 'okhttp/5.1.0';
// 内置线路池：全部来自 2026-11-12 真机抓包 + 实测可达，不臆造域名。
// ★不收录 https://app.taoyuewenhua.net：该域仅用于 assetlinks.json（manifest 实锤），
//   实测根路径 403，放进线路池会误导用户切到不可用线路。
// ★收录 m.taoyuewenhua.com 作为官方落地页（实测 200/7069B），但它不是 API 线路，
//   切换时 TX_switch 会把它当发布页展示，不会替换 txApiHost（见下）。
var TX_FALLBACK = [
  'https://tybook.taoyuewenhua.net',
  'https://scdn.taoyuewenhua.net',
  'https://m.taoyuewenhua.com',
  'http://scdn.taoyuewenhua.net'
];

function login() { return 'ok'; }   // 必须实现，否则点右上角 √ 抛 "Function login not implements!!!"

function TX_toast(t) {
  try { java.longToast(String(t)); } catch (e) { try { java.toast(String(t)); } catch (e2) {} }
}
function TX_gv(k, def) {
  var v = '';
  try { v = String(source.get(k)); } catch (e) { v = ''; }
  if (v === '' || v === 'null' || v === 'undefined') v = def || '';
  return v;
}
function TX_norm(u) {
  var s = String(u || '').trim().replace(/\/+$/, '');
  if (!s) return '';
  if (s.indexOf('http') !== 0) s = 'https://' + s;
  var m = /^(https?:\/\/[^/]+)/.exec(s);
  return m ? m[1] : s;
}
function TX_of(u) {
  var m = /^https?:\/\/([^/]+)/.exec(String(u));
  return m ? m[1] : String(u);
}
function TX_hdr() { return JSON.stringify({'User-Agent': TX_UA}); }
function TX_refresh() {
  try { java.reLoginView(false); } catch (e) {
    try { java.reUiView(false); } catch (e2) {}
  }
}

// ---------- 发布页输入框 ----------
function TX_pub() {
  var p = TX_norm(TX_gv('txPub', TX_PUB_DEFAULT));
  return p || TX_PUB_DEFAULT;
}
function TX_pubFrom(r) {
  var v = '';
  try { if (r && r.get) v = String(r.get('发布页') || ''); } catch (e0) {}
  if (!v) { try { v = String(r['发布页'] || ''); } catch (eA) {} }
  if (!v) { try { if (result && result.get) v = String(result.get('发布页') || ''); } catch (e1) {} }
  if (!v) { try { if (result) v = String(result['发布页'] || ''); } catch (eB) {} }
  if (!v || !v.trim()) v = TX_PUB_DEFAULT;
  var p = TX_norm(v);
  TX_toast('⏳ 正在应用发布页：' + TX_of(p) + ' …');
  try { source.put('txPub', p); } catch (e) { TX_toast('❌ 写入失败：' + e); return; }
  TX_toast('✅ 发布页已设为 ' + TX_of(p) + '，请点「🧭 一键从发布页获取网址路线」');
  TX_refresh();
}

// ---------- 线路池持久化 ----------
function TX_setFound(list) {
  var out = [], i, u;
  for (i = 0; i < list.length && out.length < TX_MAX; i++) {
    u = TX_norm(list[i]);
    if (u && out.indexOf(u) < 0) out.push(u);
  }
  if (!out.length) out = TX_FALLBACK.slice(0);
  try { source.put('txFound', out.join(' ')); } catch (e) {}
  for (i = 0; i < TX_MAX; i++) { try { source.put('txDelay' + i, ''); } catch (e2) {} }
  return out;
}
function TX_found() {
  var s = TX_gv('txFound', '');
  if (!s) return TX_setFound(TX_FALLBACK);
  var a = s.split(/\s+/), out = [], i;
  for (i = 0; i < a.length && out.length < TX_MAX; i++) {
    var u = TX_norm(a[i]);
    if (u.indexOf('http') === 0 && out.indexOf(u) < 0) out.push(u);
  }
  return out.length ? out : TX_setFound(TX_FALLBACK);
}
// ★不能用 .map(TX_host)：jsLib 的 TX_host(sv) 需要显式 source 参数，作为 map 回调会拿到
//   (element,index,array) 三个实参导致返回错值甚至抛错，中断按钮后半段 Toast。统一改 TX_of。
function TX_foundText() { return TX_found().map(TX_of).join(' / '); }

// ---------- 🧭 一键从发布页获取网址路线 ----------
// 分阶段 Toast：开始 → 抓取 → 解析 → 写池 → 完成 / 失败兜底
function TX_fetchPub() {
  var pub = TX_pub();
  TX_toast('🧭 阶段1/4：正在打开发布页 ' + TX_of(pub) + ' …');
  var raw = '', err = '', ms = 0;
  try {
    var t0 = Date.now();
    var r0 = java.connect(pub + '/', TX_hdr(), 12000);
    ms = Date.now() - t0;
    raw = String(r0.body());
    if (r0.code && r0.code() !== 200) err = 'HTTP ' + r0.code();
  } catch (e) { err = String(e).substring(0, 90); }
  if (!err && (raw.length < 20 || raw.indexOf('Exception') === 0)) err = '内容异常(' + raw.length + 'B)';
  if (err) {
    TX_toast('⚠ 阶段1失败：' + err + '；载入内置 ' + TX_FALLBACK.length + ' 条兜底线路');
    TX_setFound(TX_FALLBACK);
    TX_toast('✅ 已载入内置线路，请点「⏱ 检测路线延迟」测速');
    TX_refresh(); return;
  }
  TX_toast('🔓 阶段2/4：发布页已获取(' + raw.length + 'B / ' + ms + 'ms)，正在解析同族域名…');
  var lines = [], m, u, hn;
  // 从发布页正文抽取 taoyuewenhua.com/net 同族域名（排除纯资源/图床）
  var re = /https?:\/\/([a-z0-9][a-z0-9.\-]*\.taoyuewenhua\.(?:com|net))/gi;
  while ((m = re.exec(raw)) !== null) {
    u = TX_norm(m[0]); hn = TX_of(u);
    if (lines.indexOf(u) < 0) lines.push(u);
  }
  // 发布页自身 host 也算一条路线
  var self = TX_norm(pub);
  if (self && lines.indexOf(self) < 0) lines.push(self);
  // ★池首固定为「当前正在用的 API 主线路」，发布页解析出的域追加在后：
  //   避免用户打开面板看到的第 1 个按钮是落地页（不是 API），误点后以为切了线路。
  var lines2 = [TX_norm(TX_gv('txApiHost', TX_API_DEFAULT))];
  var i;
  for (i = 0; i < lines.length && lines2.length < TX_MAX; i++) {
    if (lines2.indexOf(lines[i]) < 0) lines2.push(lines[i]);
  }
  // 内置兜底补齐（真机抓包实锤的线路）
  for (i = 0; i < TX_FALLBACK.length && lines2.length < TX_MAX; i++) {
    if (lines2.indexOf(TX_FALLBACK[i]) < 0) lines2.push(TX_FALLBACK[i]);
  }
  lines = lines2;
  TX_toast('🔎 阶段3/4：解析到 ' + lines.length + ' 条候选，正在写入线路按钮…');
  var got = TX_setFound(lines);
  TX_toast('✅ 阶段4/4：共 ' + got.length + ' 条路线 → ' + got.map(TX_of).join(' / '));
  TX_toast('📌 延时尚未写入，请点「⏱ 检测路线延迟（ms写入路线按钮）」');
  TX_refresh();
}

// ---------- ⏱ 检测路线延迟（ms 写进各网址按钮） ----------
// 判活按线路类型分别走真实可用路径（全部为非搜索接口，用户主动点击才触发）：
//   · tybook API 线路 → 现算 sign 的 /auth/account.do（游客账户探针，返回 errcode:0）
//   · scdn CDN 线路   → 免签名静态目录 /app/chapters/{bid}.json
//   · 官方落地页 m.   → 根路径 HTML（200 / 7069B）
// ★坑（实测）：tybook 根路径返回 39B 的 {"errcode":202,"errmsg":"Empty app id"}，
//   用「根路径 + 长度阈值」判活会把正常 API 线路误标成「内容异常」；必须用带完整
//   参数的签名接口。java.connect 失败时返回异常堆栈串而非抛异常，须显式排除。
function TX_probeUrl(u) {
  if (u.indexOf('scdn.taoyuewenhua.net') > -1) {
    return u + '/app/chapters/yw_20120838908848304.json';
  }
  if (u.indexOf('tybook.taoyuewenhua.net') > -1) {
    return TX_url(java, TX_params({}), u, '/auth/account.do');
  }
  return u + '/';
}
function TX_testAll() {
  var list = TX_found();
  TX_toast('⏱ 阶段1/3：开始测速，共 ' + list.length + ' 条路线（非搜索接口，不触发搜索风控）…');
  var i, r, b, ms, tag, best = -1, bestMs = 999999;
  for (i = 0; i < list.length; i++) {
    ms = -1; tag = '✗ 不可达';
    try {
      var t0 = Date.now();
      r = java.connect(TX_probeUrl(list[i]), TX_hdr(), 10000);
      b = String(r.body());
      if (b.indexOf('Exception') > -1 || b.indexOf('timeout') > -1) {
        tag = '✗ 不可达';
      } else if (r.code && (r.code() < 200 || r.code() >= 400)) {
        tag = '✗ HTTP/' + r.code();
      } else if (b.indexOf('"errcode":0') > -1 || b.indexOf('"chapterList"') > -1 || b.length > 500) {
        ms = Date.now() - t0;
        try { if (r.callTime) { var ct = Number(r.callTime()); if (ct > 0) ms = ct; } } catch (eC) {}
        tag = ms + 'ms';
        if (ms < bestMs) { bestMs = ms; best = i; }
      } else {
        tag = '✗ 内容异常(' + b.length + 'B)';
      }
    } catch (e) { tag = '✗ ' + String(e).substring(0, 24); }
    try { source.put('txDelay' + i, tag); } catch (e2) {}
    TX_toast('  · 路线' + (i + 1) + ' ' + TX_of(list[i]) + ' → ' + tag);
  }
  TX_toast('📝 阶段2/3：延时已写入各网址按钮，正在刷新面板…');
  if (best >= 0) {
    try { source.put('txBest', String(best)); } catch (e3) {}
    try { source.put('txDelay' + best, '⚡' + bestMs + 'ms'); } catch (e4) {}
  }
  TX_refresh();
  TX_toast('✅ 阶段3/3：测速完成' + (best >= 0 ? '，最快 ' + TX_of(list[best]) + ' ⚡' + bestMs + 'ms（未自动切换，请手动点路线按钮）' : '，全部不可达'));
}

// ---------- 🔍 检查登录状态 ----------
// 本源是游客态：无账号体系。该按钮给出「是否需要登录」的明确结论 + 凭证健康度。
// 只打 /auth/account.do（非搜索接口），不会触发搜索风控。
function TX_checkLogin() {
  TX_toast('🔍 阶段1/3：正在检查游客凭证与接口连通性…');
  var p = TX_params({});
  var api = TX_gv('txApiHost', TX_API_DEFAULT);
  var u = TX_url(java, p, api, '/auth/account.do');
  var r = null, b = '', code = 0;
  try { r = java.connect(u, TX_hdr(), 10000); b = String(r.body()); code = Number(r.code()); }
  catch (e) { b = 'Exception ' + e; }
  var ok = code >= 200 && code < 400 && b.indexOf('"errcode":0') > -1;
  var isVip = /"isVip":true/.test(b);
  TX_toast('📡 阶段2/3：/auth/account.do → HTTP ' + code + ' / ' + b.length + 'B');
  if (ok) {
    TX_toast('✅ 阶段3/3：游客凭证有效，无需登录（isVip=' + isVip + '）；搜索/详情/目录/正文均可用');
  } else {
    TX_toast('❌ 阶段3/3：接口异常 ' + b.slice(0, 100) + '；请在「路线」里切换到 ⚡ 最快线路后重试');
  }
  try { source.put('txLoginCheck', ok ? '游客态正常' : '异常'); } catch (e2) {}
  TX_refresh();
}
function TX_web() {
  TX_toast('🌐 正在打开官方落地页 ' + TX_of(TX_pub()) + ' …');
  try { java.openUrl(TX_pub()); TX_toast('✅ 已调起浏览器'); }
  catch (e) { TX_toast('⚠ 无法调起浏览器：' + String(e).slice(0, 80) + '；地址：' + TX_pub()); }
}

// ---------- 线路切换（各网站一个按钮） ----------
// 切线路时同时写 txApiHost / txCdnHost：若选中的是 scdn 则只切 CDN，API 保持默认；
// 其余线路切 API。这样「各网站点击切换」对真实生效的域名语义正确。
function TX_switch(n) {
  var list = TX_found();
  if (n < 1 || n > list.length) { TX_toast('⚠ 路线' + n + ' 不存在，当前只有 ' + list.length + ' 条'); return; }
  var u = list[n - 1];
  TX_toast('⏳ 正在切换到路线' + n + '：' + TX_of(u) + ' …');
  try {
    if (u.indexOf('scdn.taoyuewenhua.net') > -1) {
      // CDN 线路：只切目录域名，API 保持默认
      source.put('txCdnHost', u);
      source.put('txApiHost', TX_API_DEFAULT);
    } else if (u.indexOf('tybook.taoyuewenhua.net') > -1) {
      // 主 API 线路：切 API，CDN 回默认
      source.put('txApiHost', u);
      source.put('txCdnHost', TX_CDN_DEFAULT);
    } else {
      // 官方落地页等「非 API 域」：只记发布页，不动 API/CDN，
      // 避免用户误切到 403 的 assetlinks 域导致整源不可用。
      source.put('txPub', u);
    }
    source.put('txLine', String(n));
  } catch (e) { TX_toast('❌ 写入失败：' + e); return; }
  TX_toast('✅ 已切换到 ' + TX_of(u) + '；请重新搜索/刷新书城验证');
  TX_refresh();
}

// ---------- viewName 动态文本（只读 source，不碰 java） ----------
// ★viewName 为 JS 表达式时，求值结果经 normalizeJsResult「原样显示、不剥引号」
//   （源码级实锤），因此这两个函数返回纯文本，禁止自带外层单引号。
function TX_lineBtn(n) {
  var list = TX_found();
  if (n > list.length) return '— 备用位 —';
  var u = list[n - 1];
  var d = TX_gv('txDelay' + (n - 1), '');
  var cur = '';
  try { cur = String(source.get('txLine') || ''); } catch (e) {}
  var mark = (String(n) === cur) ? '● ' : '○ ';
  return mark + TX_of(u) + (d ? ' ' + d : '');
}
function TX_curLineText() {
  var api = TX_gv('txApiHost', TX_API_DEFAULT);
  var cdn = TX_gv('txCdnHost', TX_CDN_DEFAULT);
  var st = TX_gv('txLoginCheck', '未检查');
  return '当前 API：' + TX_of(api) + ' ｜ CDN：' + TX_of(cdn) + ' ｜ 状态：' + st;
}

