// ===== 淘小说 11.2.8 公共签名库 =====
// sign = MD5( 全部请求参数按 key 字典序排列、值用 UTF-8 明文拼接 + "&key=mibook_123456" ).toUpperCase()
// 实锤：ProxyPin 抓包 112 条请求离线碰撞 112/112 命中；App 内 java.md5Encode 复算一致。
// 注意：sign 的是「解码后的参数值」；URL 里才 encodeURIComponent。
// 注意：key 也要参与排序（当业务参数恰好含 key 时不可重复追加）。
function TX_signBase(p) {
  var ks = Object.keys(p).sort();
  var s = '';
  for (var i = 0; i < ks.length; i++) {
    if (i) s += '&';
    s += ks[i] + '=' + String(p[ks[i]]);
  }
  return s;
}
function TX_query(p) {
  var ks = Object.keys(p).sort();
  var q = '';
  for (var i = 0; i < ks.length; i++) {
    if (i) q += '&';
    q += ks[i] + '=' + encodeURIComponent(String(p[ks[i]]));
  }
  return q;
}
// jv = java 绑定（规则 @js 环境），显式传入以兼容 jsLib 共享 scope
function TX_url(jv, p, host, path) {
  var sign = String(jv.md5Encode(TX_signBase(p) + '&key=mibook_123456')).toUpperCase();
  return host + path + '?' + TX_query(p) + '&sign=' + sign;
}

// 11.2.8 真机抓包的固定设备/游客参数。
// 对照实验实锤：book_rank/tf/book/tf/chapter_content 只校验 sign，token↔uid 可任意；
// 唯独 /authopt/ty/search_books 额外校验 token↔uid 配对（伪造 → errcode 205 Invalid token）。
// 故此处使用真机抓包的那组配对凭证，绝不自造。
function TX_dev() {
  return {
    android_id: '76546fb5b7fa81c2',
    appid: 'mibook',
    brand: 'Xiaomi',
    channel: 'XiaoMi',
    device_id: '38825f4366714ddba026677ee69a004c',
    model: 'MI 8',
    optype: '0',
    ostype: '0',
    osversion: '10',
    package_name: 'com.martian.ttbook',
    token: 'a8976c97-ab2f-4bac-b4a6-389475e77719',
    uid: '85861337',
    version_code: '801',
    version_name: '11.2.8'
  };
}
// 服务端不校验 t 时效（2022 年旧时间戳 / 未来时间戳 / 当前时间戳 三组均 errcode:0），
// 但仍每次用当前时间，避免任何潜在的日志侧异常。
function TX_params(extra) {
  var p = TX_dev();
  if (extra) for (var k in extra) p[k] = extra[k];
  p.t = String(Date.now());
  return p;
}

// 面板切换的线路：sv = source 绑定，由规则 @js 显式传入。
// ★jsLib 共享 scope 不注入任何规则环境绑定（java/book/source/result/baseUrl 全无，源码级实锤），
//   所以本文件里所有函数一律「显式传参」，绝不裸用 source/java。
function TX_host(sv) {
  var d = '';
  try { d = String(sv.get('txApiHost') || ''); } catch (e) { d = ''; }
  if (!d || d.indexOf('http') !== 0) d = 'https://tybook.taoyuewenhua.net';
  return d.replace(/\/+$/, '');
}
function TX_cdn(sv) {
  var d = '';
  try { d = String(sv.get('txCdnHost') || ''); } catch (e) { d = ''; }
  if (!d || d.indexOf('http') !== 0) d = 'https://scdn.taoyuewenhua.net';
  return d.replace(/\/+$/, '');
}

// ===== 各规则入口（jv=java、sv=source，全部由规则 @js 显式传入） =====
// 搜索：/authopt/ty/search_books，Legado 的 page 从 1 开始，接口 page 从 0 开始
function TX_search(jv, sv, key, page) {
  var p = TX_params({
    ctype: '1',
    keywords: String(key),
    page: String((Number(page) || 1) - 1),
    pageSize: '10',
    searchType: '1',
    sourceName: 'yw'
  });
  return TX_url(jv, p, TX_host(sv), '/authopt/ty/search_books');
}
// 搜索/发现列表里的 bookUrl：/tf/book?bid=xxx
function TX_bookUrl(jv, sv, bid) {
  var p = TX_params({ bid: String(bid) });
  return TX_url(jv, p, TX_host(sv), '/tf/book');
}
// 详情 → 目录：/tf/chapter_list 302 跳到免签名 CDN，Legado 网络栈自动跟随
// 极简参数报 errcode 202 Empty app id ⇒ 必须带 TX_dev() 全套参数（实锤）
function TX_tocUrl(jv, sv, bid) {
  var p = TX_params({ bid: String(bid), retry: '0' });
  return TX_url(jv, p, TX_host(sv), '/tf/chapter_list');
}
// 目录章节 → 正文：/tf/chapter_content?bid=&cid=&autoBuy=true
function TX_contentUrl(jv, sv, bid, cid) {
  var p = TX_params({ bid: String(bid), cid: String(cid), autoBuy: 'true' });
  return TX_url(jv, p, TX_host(sv), '/tf/chapter_content');
}
// 发现页：book_rank 榜单 / search_by_category 分类 / channel_books 书城频道 / search_recommend
// 站点无「下一页」字段，终止判据用「本页返回空 / 与上一页内容重复」由 Legado 自己处理，
// 不写死页码上限（用户明确要求：站点以后加书要能自动继续）。
function TX_explore(jv, sv, path, extra, page) {
  var e = {};
  if (extra) for (var k in extra) e[k] = extra[k];
  e.page = String((Number(page) || 1) - 1);
  e.pageSize = '10';
  var p = TX_params(e);
  return TX_url(jv, p, TX_host(sv), path);
}

// 供用户粘贴 App 分享链接时反解 bid（bookUrlPattern 命中后由详情页规则使用）
function TX_bidFrom(u) {
  var m = /[?&]bid=([^&#]+)/.exec(String(u));
  return m ? decodeURIComponent(m[1]) : '';
}

